// object (llmRequestBody) via native JSON body mode, never a raw interpolated
// string. This removes the unvalidated raw-string handoff that produced an
// empty-body HTTP 400 at "de Patch - HTTP Request" in attempt 7.
const dePatchHttp = node('de Patch - HTTP Request');
const { body: _legacyBody, contentType: _legacyContentType, rawContentType: _legacyRawContentType, ...jsonHttpBaseParams } = dePatchHttp.parameters;
jsonHttpBaseParams.sendBody = true;
jsonHttpBaseParams.specifyBody = 'json';
dePatchHttp.parameters = { ...jsonHttpBaseParams, jsonBody: '={{ $json.llmRequestBody }}' };
delete dePatchHttp.retryOnFail;
delete dePatchHttp.maxTries;
delete dePatchHttp.waitBetweenTries;

