const balancedJsonHelper = String.raw`const parseFirstBalancedJson=(raw,parserStage)=>{const text=String(raw??'').replace(/^\uFEFF/,'');for(let start=0;start<text.length;start++){const opening=text[start];if(opening!=='{'&&opening!=='[')continue;const stack=[opening==='{'?'}':']'];let inString=false;let escaped=false;for(let i=start+1;i<text.length;i++){const ch=text[i];if(inString){if(escaped){escaped=false;continue}if(ch==='\\'){escaped=true;continue}if(ch==='"')inString=false;continue}if(ch==='"'){inString=true;continue}if(ch==='{'){stack.push('}');continue}if(ch==='['){stack.push(']');continue}if(ch==='}'||ch===']'){if(stack[stack.length-1]!==ch)break;stack.pop();if(stack.length===0){const candidate=text.slice(start,i+1);try{return JSON.parse(candidate)}catch{break}}}}}throw new Error('CLAUDE_JSON_EXTRACTION_FAILED:'+JSON.stringify({parserStage,category:'NO_VALID_BALANCED_JSON'}))};`;

// Preserve validated source/stage semantics and keep specialist domains out of
