const body=input.body||input;const envelope=input.correlationEnvelope||{};const required=['incidentId','projectId','requestId','remediationType','repository'];const missing=required.filter(k=>!body[k]);if(missing.length)throw new Error('INVALID_APPROVAL_CONTRACT:'+missing.join(','));if(body.remediationType!=='AUTO_FIX_ELIGIBLE')throw new Error('MANUAL_ACTION_REQUIRED');
const findings=Array.isArray(body.findings)?body.findings:body.finding?[body.finding]:[];const findingIds=[...new Set((Array.isArray(body.findingIds)?body.findingIds:body.findingId?[body.findingId]:[]).map(String))].sort();if(!findings.length||!findingIds.length||findings.length!==findingIds.length)throw new Error('INVALID_BATCH_FINDINGS');
