const sources=[...new Set(normalizedFindings.map(f=>f.source))],stages=[...new Set(normalizedFindings.map(f=>f.stage))];if(sources.length!==1||stages.length!==1)throw new Error('WF2_MIXED_SOURCE_BATCH_UNSUPPORTED:'+JSON.stringify({sources,stages}));const source=sources[0],stage=stages[0];
const targetFiles=[...new Set(normalizedFindings.map(f=>String(f.file||f.component||'').replace(/^[^:]+:/,'')).filter(Boolean))];if(!targetFiles.length||targetFiles.some(target=>target.startsWith('/')||target.includes('..')))throw new Error('UNSAFE_OR_MISSING_TARGET_FILE');const parts=String(body.repository).replace('https://github.com/','').replace(/\.git$/,'').split('/').filter(Boolean);if(parts.length!==2)throw new Error('INVALID_REPOSITORY');
return [{json:{incidentData:{incidentId:envelope.incidentId,projectId:envelope.projectId,buildNumber:envelope.buildNumber,batchKey:envelope.batchKey,batchId:envelope.batchId,attemptCount:envelope.attemptCount,findingId:findingIds[0],findingIds,requestId:envelope.requestId,approvedBy:body.approvedBy||null,stage,source,remediationType:body.remediationType,githubRepo:parts.join('/'),repository_owner:parts[0],repository_name:parts[1],target_file_path:targetFiles[0],targetFiles,default_branch:body.defaultBranch||null,finding:normalizedFindings[0],findings:normalizedFindings,decision:'FIX_PROPOSED',confidenceScore:1,riskLevel:String(normalizedFindings[0].severity||'high').toLowerCase(),enrichedData:{source,stage,findings:normalizedFindings}}}}];`;

// Repository authorization is deterministic and precedes every LLM call.
const preparePolicy = codeNode('Build Independent Repository Policy', String.raw`
