return [{json:{...ctx,remediationContract:contract,llmRequestBody,planBodyString:serializedRequestBody,requestBodyPresent:true,serializedBodyLength:serializedRequestBody.length,messagesCount:llmRequestBody.messages.length,hasOutputConfig:Boolean(llmRequestBody.output_config)}}];`, [-2500,3900]);

const parsePlan = codeNode('Validate Generic Remediation Plan', String.raw`
