const extractClaudeText=response=>{const stopReason=String(response?.stop_reason||'');const blocks=Array.isArray(response?.content)?response.content:[];const types=blocks.map(block=>String(block?.type||'unknown'));const texts=typeof response?.content==='string'?[response.content]:blocks.filter(block=>block&&block.type==='text'&&typeof block.text==='string').map(block=>block.text).filter(text=>text.trim().length>0);if(!texts.length&&typeof response?.content?.text==='string'&&response.content.text.trim())texts.push(response.content.text);const diagnostic=JSON.stringify({parserStage:'planner',model:String(response?.model||'claude-sonnet-5'),stop_reason:stopReason||null,contentBlockTypes:types,contentBlockCount:blocks.length,textBlockCount:texts.length});if(stopReason==='refusal')throw new Error('WF2_LLM_REFUSAL:'+diagnostic);if(!texts.length)throw new Error('CLAUDE_EMPTY_TEXT_RESPONSE:'+diagnostic);return texts.join('\n')};
